def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # check if existing entry is expired
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]

            if key in cache:
                # update existing entry, make most recently used
                cache.move_to_end(key)
                cache[key] = (value, t)
            else:
                # clean up expired entries so capacity count is accurate
                expired_keys = [k for k, (v, wt) in cache.items() if t >= wt + ttl]
                for k in expired_keys:
                    del cache[k]
                if len(cache) >= capacity:
                    cache.popitem(last=False)  # evict least recently used
                cache[key] = (value, t)
        else:  # 'get'
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(v)
            else:
                results.append(-1)
    return results

